23	export class GitHubService {
24	  private api: AxiosInstance;
25	  private cache: CacheManager;
26	  private repo: GitHubRepo;
27	
28	  constructor(token?: string) {
29	    this.cache = new CacheManager();
30	    
31	    // Configure axios instance with GitHub API
32	    this.api = axios.create({
33	      baseURL: 'https://api.github.com',
34	      headers: {
35	        'Accept': 'application/vnd.github.v3+json',
36	        ...(token ? { 'Authorization': `token ${token}` } : {})
37	      }
38	    });
39	
40	    // ReactBits repository details
41	    this.repo = {
42	      owner: 'DavidHDev',
43	      repo: 'react-bits'
44	    };
45	  }
46	
47	  async getFileContent(path: string): Promise<string> {
48	    const cacheKey = `github:file:${path}`;
49	    const cached = this.cache.get<string>(cacheKey);
50	    if (cached) return cached;
51	
52	    try {
53	      const response = await this.api.get<GitHubFile>(
54	        `/repos/${this.repo.owner}/${this.repo.repo}/contents/${path}`
55	      );
56	
57	      const file = response.data;
58	      
59	      if (file.type !== 'file') {
60	        throw new Error(`Path ${path} is not a file`);
61	      }
62	
63	      // Decode base64 content
64	      const content = file.content ? 
65	        Buffer.from(file.content, 'base64').toString('utf-8') : '';
66	      
67	      this.cache.set(cacheKey, content, 3600000); // Cache for 1 hour
68	      return content;
69	    } catch (error) {
70	      if (axios.isAxiosError(error)) {
71	        if (error.response?.status === 404) {
72	          throw new Error(`File not found: ${path}`);
73	        }
74	        if (error.response?.status === 403) {
75	          throw new Error('GitHub API rate limit exceeded. Please try again later.');
76	        }
77	      }
78	      throw error;
79	    }
80	  }
81	
82	  async listFiles(path: string = ''): Promise<GitHubFile[]> {
83	    const cacheKey = `github:list:${path}`;
84	    const cached = this.cache.get<GitHubFile[]>(cacheKey);
85	    if (cached) return cached;
86	
