88	      const response = await this.api.get<GitHubFile[]>(
89	        `/repos/${this.repo.owner}/${this.repo.repo}/contents/${path}`
90	      );
91	
92	      const files = response.data;
93	      this.cache.set(cacheKey, files, 3600000); // Cache for 1 hour
94	      return files;
95	    } catch (error) {
96	      if (axios.isAxiosError(error)) {
97	        if (error.response?.status === 404) {
98	          throw new Error(`Directory not found: ${path}`);
99	        }
100	        if (error.response?.status === 403) {
101	          throw new Error('GitHub API rate limit exceeded. Please try again later.');
102	        }
103	      }
104	      throw error;
105	    }
106	  }
