114	      // Search for component files in the repository
115	      const response = await this.api.get('/search/code', {
116	        params: {
117	          q: `${query} in:file extension:tsx extension:jsx repo:${this.repo.owner}/${this.repo.repo}`,
118	          per_page: 30
